function fib(n) {
  return n < 2 ? n : fib(n - 1) + fib(n - 2)
}

const seq = Array.from({ length: 10 }, (_, i) => fib(i))
console.log('Fibonacci:', seq)

const user = { name: 'Atom', langs: ['JS', 'TS'], active: true }
console.log(user)

